using System;
using System.Linq;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
internal sealed partial class ModernWorkspace {
 DateTime budgetMonth=new DateTime(DateTime.Today.Year,DateTime.Today.Month,1);
 string budgetCategory="Toutes les catégories";bool budgetAllEntries;
 string[] BudgetCategories(){return Finance.Categories.Concat(store.Value.budget.entries.Select(e=>e.category)).Concat(store.Value.budget.rules.Select(e=>e.category)).Concat(store.Value.budget.caps.Select(c=>c.category)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
 void BudgetPage(StackPanel root){
  var b=store.Value.budget;var today=DateTime.Today;var end=new DateTime(today.Year,today.Month,DateTime.DaysInMonth(today.Year,today.Month));var forecast=Finance.Forecast(b,today,end);
  BudgetToolbarV2(root);root.Children.Add(T("Saisie manuelle · montants en euros · aucune connexion bancaire",11,Muted,new Thickness(0,0,0,16)));BudgetExtraLinks(root);
  if(!b.hasBalance){var welcome=new StackPanel();welcome.Children.Add(T("Renseignez votre solde actuel pour calculer le prévisionnel. Vous pouvez déjà saisir vos dépenses et fixer vos budgets.",12,Muted,new Thickness(0,0,0,10)));welcome.Children.Add(Btn("Définir mon solde de départ",delegate{EditBudgetBalance();},true));root.Children.Add(Card("Votre budget, à votre rythme",welcome));}
  var summary=new UniformGrid{Columns=3,Margin=new Thickness(0,12,0,16)};
  foreach(var item in new[]{new[]{ "Solde estimé aujourd'hui",b.hasBalance?Finance.Money(Finance.Balance(b,today)):"À renseigner"},new[]{"Prévision au "+end.ToString("dd/MM"),b.hasBalance?Finance.Money(forecast.End):"À renseigner"},new[]{"Dépenses du mois",Finance.Money(Finance.Spent(b,today,null))}}){
   var panel=new StackPanel();panel.Children.Add(T(item[0],11,Muted));var amount=T(item[1],26,Ink,new Thickness(0,9,0,0));amount.FontFamily=new System.Windows.Media.FontFamily("Georgia");panel.Children.Add(amount);var card=Box(panel,new Thickness(16));card.Margin=new Thickness(0,0,10,0);summary.Children.Add(card);
  }root.Children.Add(summary);
  if(b.hasBalance){root.Children.Add(T("Solde de référence renseigné le "+Finance.Day(b.balanceDate).ToString("dd/MM/yyyy")+". Il reste estimatif tant que des opérations ne sont pas saisies.",11,Muted,new Thickness(0,0,0,14)));root.Children.Add(T(b.overdraftKnown?"Découvert autorisé : "+Finance.Money(b.overdraftCents)+" · seuil −"+Finance.Money(b.overdraftCents):"Découvert autorisé : non renseigné.",11,Muted,new Thickness(0,0,0,14)));if(forecast.Minimum<0)root.Children.Add(Card(Finance.ExceedsOverdraft(b,forecast.Minimum)?"Dépassement du découvert autorisé":"Solde négatif prévu",T("Le prévisionnel descend à "+Finance.Money(forecast.Minimum)+" le "+forecast.MinimumDate.ToString("dd/MM")+". "+Finance.OverdraftSummary(b,forecast.Minimum),13,Accent)));}
  var monthTools=new WrapPanel{Margin=new Thickness(0,18,0,15)};monthTools.Children.Add(Btn("‹",delegate{if(budgetMonth.Year>1900){budgetMonth=budgetMonth.AddMonths(-1);Refresh();}},false,true));monthTools.Children.Add(Btn("Ce mois",delegate{budgetMonth=new DateTime(today.Year,today.Month,1);Refresh();},false,true));monthTools.Children.Add(Btn("›",delegate{if(budgetMonth.Year<2200){budgetMonth=budgetMonth.AddMonths(1);Refresh();}},false,true));monthTools.Children.Add(T(budgetMonth.ToString("MMMM yyyy",CultureInfo.GetCultureInfo("fr-FR")),19,Ink,new Thickness(10,8,0,0)));root.Children.Add(monthTools);
  var categories=new StackPanel();
  foreach(var cap in b.caps){var item=cap;long spent=Finance.Spent(b,budgetMonth,item.category);var row=new StackPanel{Margin=new Thickness(0,0,0,14)};row.Children.Add(T(item.category+" · "+Finance.Money(spent)+" / "+Finance.Money(item.cents),13));row.Children.Add(new ProgressBar{Minimum=0,Maximum=100,Value=Math.Min(100,100.0*spent/item.cents),Height=4,Foreground=Accent,Background=Line,BorderThickness=new Thickness(0),Margin=new Thickness(0,9,0,7)});row.Children.Add(T(spent>item.cents?"Dépassé de "+Finance.Money(spent-item.cents):"Reste "+Finance.Money(item.cents-spent),11,spent>item.cents?Accent:Muted));row.Children.Add(Btn("Modifier",delegate{EditBudgetCap(item);},false,true));categories.Children.Add(row);}
  if(b.caps.Count==0)categories.Children.Add(T("Définissez par exemple une enveloppe mensuelle Courses ou Carburant.",12,Muted));root.Children.Add(Card("Mes enveloppes mensuelles",categories));PlannedBudgetSection(root);
  var upcoming=new StackPanel();
  if(forecast.Pending.Count==0)upcoming.Children.Add(T("Aucune opération prévue à venir d'ici la fin du mois.",12,Muted));
  foreach(var occurrence in forecast.Pending.Take(40)){var item=occurrence;var row=new DockPanel{Margin=new Thickness(0,8,0,8)};if(item.Date<=today){var paid=Btn("Confirmer passée",delegate{ConfirmBudgetOccurrence(item);},false,true);DockPanel.SetDock(paid,Dock.Right);row.Children.Add(paid);}var info=new StackPanel();info.Children.Add(T(item.Rule.title+" · "+(item.Rule.kind=="income"?"+":"−")+Finance.Money(item.Rule.cents),13));info.Children.Add(T(item.Date.ToString("dd/MM/yyyy")+(item.Date<today?" · En attente de confirmation":" · Prévu"),11,Muted,new Thickness(0,4,0,0)));row.Children.Add(info);upcoming.Children.Add(row);}
  if(forecast.Pending.Count>40)upcoming.Children.Add(T("40 premières échéances affichées ; toutes sont incluses dans le calcul.",11,Muted));
  upcoming.Children.Add(T("Les prévisions ne deviennent des opérations réelles qu'après confirmation. Revenus et dépenses du même jour sont regroupés dans le calcul.",11,Muted,new Thickness(0,12,0,0)));var upcomingCard=Card("Prévu jusqu'à la fin du mois",upcoming);upcomingCard.Margin=new Thickness(0,16,0,16);root.Children.Add(upcomingCard);
  var rules=new StackPanel();foreach(var rule in b.rules.Where(r=>r.repeat!="once")){var item=rule;rules.Children.Add(Btn(item.title+" · "+(item.kind=="income"?"+":"−")+Finance.Money(item.cents)+" · "+(item.repeat=="weekly"?"hebdomadaire":item.repeat=="yearly"?"annuel":"mensuel"),delegate{EditBudgetRule(item);},false,true));}if(!b.rules.Any(r=>r.repeat!="once"))rules.Children.Add(T("Ajoutez votre salaire, loyer ou abonnements avec leur date de passage.",12,Muted));root.Children.Add(Card("Mes récurrences",rules));
  var journal=new StackPanel();var filter=new WrapPanel{Margin=new Thickness(0,0,0,12)};var category=Combo(new[]{"Toutes les catégories"}.Concat(BudgetCategories()),budgetCategory);category.Width=210;filter.Children.Add(category);filter.Children.Add(Btn("Filtrer",delegate{budgetCategory=Convert.ToString(category.SelectedItem);Refresh();},false,true));filter.Children.Add(Btn(budgetAllEntries?"Voir ce mois":"Tout l'historique",delegate{budgetAllEntries=!budgetAllEntries;Refresh();},false,true));journal.Children.Add(filter);
  var entries=b.entries.Where(e=>(budgetAllEntries||(Finance.Day(e.date).Year==budgetMonth.Year&&Finance.Day(e.date).Month==budgetMonth.Month))&&(budgetCategory=="Toutes les catégories"||String.Equals(e.category,budgetCategory,StringComparison.OrdinalIgnoreCase))).OrderByDescending(e=>e.date).ToList();
  long income=entries.Where(e=>e.kind=="income").Sum(e=>e.cents),expense=entries.Where(e=>e.kind=="expense").Sum(e=>e.cents);journal.Children.Add(T(entries.Count+" opération(s) · revenus "+Finance.Money(income)+" · dépenses "+Finance.Money(expense),11,Muted,new Thickness(0,0,0,12)));
  foreach(var entry in entries.Take(100)){var item=entry;var row=new DockPanel{Margin=new Thickness(0,5,0,5)};var edit=Btn("Modifier",delegate{EditBudgetEntry(item,item.kind);},false,true);DockPanel.SetDock(edit,Dock.Right);row.Children.Add(edit);var text=new StackPanel();text.Children.Add(T(item.title+" · "+(item.kind=="income"?"+":"−")+Finance.Money(item.cents),13));text.Children.Add(T(Finance.Day(item.date).ToString("dd/MM/yyyy")+" · "+item.category,11,Muted,new Thickness(0,4,0,0)));row.Children.Add(text);journal.Children.Add(row);}
  if(entries.Count>100)journal.Children.Add(T("100 opérations affichées. Les totaux incluent toute la sélection ; filtrez par mois ou catégorie pour retrouver les autres.",11,Muted));if(entries.Count==0)journal.Children.Add(T("Aucune opération dans cette sélection.",12,Muted));var journalCard=Card("Mes opérations",journal);journalCard.Margin=new Thickness(0,16,0,0);root.Children.Add(journalCard);ReflowBudgetV2(root);
 }
 StackPanel BudgetHome(bool compact){
  var b=store.Value.budget;var body=new StackPanel();if(!b.hasBalance)body.Children.Add(T("Renseignez votre solde pour suivre votre prévisionnel.",12,Muted));
  else{var today=DateTime.Today;var forecast=Finance.Forecast(b,today,new DateTime(today.Year,today.Month,DateTime.DaysInMonth(today.Year,today.Month)));body.Children.Add(T("Solde estimé · "+Finance.Money(Finance.Balance(b,today)),19));body.Children.Add(T("Fin de mois · "+Finance.Money(forecast.End),12,Muted,new Thickness(0,9,0,0)));if(forecast.Minimum<0)body.Children.Add(T((Finance.ExceedsOverdraft(b,forecast.Minimum)?"Limite de découvert dépassée":"Solde négatif prévu")+" · "+Finance.Money(forecast.Minimum),12,Accent,new Thickness(0,9,0,0)));if(!compact)body.Children.Add(T(b.overdraftKnown?"Découvert autorisé · "+Finance.Money(b.overdraftCents):"Découvert autorisé non renseigné",11,Muted,new Thickness(0,9,0,0)));if(!compact)body.Children.Add(T("Dépenses du mois · "+Finance.Money(Finance.Spent(b,today,null)),11,Muted,new Thickness(0,9,0,0)));}
  body.Children.Add(Btn("+ Dépense",delegate{EditBudgetEntry(null,"expense");},false,true));return body;
 }
}
